  txt(addG, '(does not occur)', 733, 282, { size: 16, weight: 'bold', fill: MAG });
  hit(addG, 642, 56, 186, 240);
  bind(addG, 'Addition product: non-aromatic dibromide — higher in energy than the reactants',
    'The addition product that never forms',
    'Adding Br⁻ to the cation would give 5,6-dibromocyclohexa-1,3-diene: two sp³ carbons, only two isolated double bonds, and no aromatic ring. Its energy lies above benzene + Br₂, so this branch is uphill overall and aromatic compounds undergo substitution instead of addition.');

  /* glows */
  function glow(cx, cy, rx, ry) {
    return glowLayer.ellipse(rx * 2, ry * 2).center(cx, cy).fill({ color: '#ffe680', opacity: 1 }).opacity(0);
  }
  var glowReact = glow(218, 368, 122, 60);
  var glowCation = glow(455, 196, 98, 80);
  var glowProd = glow(720, 438, 142, 80);
  var glowAdd = glow(730, 158, 118, 142);

  /* caption */
  txt(draw, 'Reaction progress', 452, 560, { size: 17 });
  draw.line(548, 560, 636, 560).stroke({ color: MAG, width: 3 });
  draw.polygon(ptsStr([[650, 560], [634, 553], [634, 567]])).fill(MAG);

  /* stage marker */
  var markerG = draw.group().opacity(0);
  var markerRing = markerG.circle(28).center(0, 0).fill({ color: '#ffd24d', opacity: 0.55 });
  var marker = markerG.circle(15).center(0, 0).fill('#ffb400').stroke({ color: '#000', width: 2 });

  /* ---------------- state ---------------- */
  window.STAGE_NAMES = ['reactants', 'first transition state', 'cationic intermediate', 'second transition state', 'products'];
  var stageIdx = 0, branch = 'Substitution', engaged = false;

  var STAGE_TIP = [
    'Reactants: benzene + Br₂ on the baseline',
    'TS1 — the highest point: rate-limiting attack on Br⁺',
    'Intermediate: cyclohexadienyl cation in a real energy well',
    'TS2 — a much lower barrier',
    'Products'
  ];

  function stagePoint() {
    if (stageIdx === 0) return SUB[0];
    if (stageIdx === 1) return SUB[TS1_I];
    if (stageIdx === 2) return SUB[TROUGH_I];
    if (stageIdx === 3) return (branch === 'Substitution') ? SUB[TS2_I] : ADD[ADDMAX_I];
    return (branch === 'Substitution') ? SUB[SUB.length - 1] : ADD[ADD.length - 1];
  }

  function render() {
    var subActive = (branch === 'Substitution');

    if (!engaged) {
      subLine.stroke({ color: BLK, width: 3.2 });
      addLine.stroke({ color: MAG, width: 3.2 });
      subHalo.opacity(0); addHalo.opacity(0);
      prodG.opacity(1); addG.opacity(1);
      markerG.opacity(0);
      glowReact.opacity(0); glowCation.opacity(0); glowProd.opacity(0); glowAdd.opacity(0);
    } else {
      subLine.stroke({ color: subActive ? BLK : GRAY, width: subActive ? 4.2 : 2.6 });
      addLine.stroke({ color: subActive ? GRAY : MAG, width: subActive ? 2.6 : 4.2 });
      subHalo.opacity(subActive ? 0.55 : 0);
      addHalo.opacity(subActive ? 0 : 0.55);
      prodG.opacity(subActive ? 1 : 0.32);
      addG.opacity(subActive ? 0.32 : 1);

      var p = stagePoint();
      markerG.opacity(1);
      markerRing.center(p[0], p[1]);
      marker.center(p[0], p[1]);

      glowReact.opacity(stageIdx === 0 ? 0.5 : 0);
      glowCation.opacity(stageIdx === 2 ? 0.5 : 0);
      glowProd.opacity((stageIdx === 4 && subActive) ? 0.5 : 0);
      glowAdd.opacity((stageIdx === 4 && !subActive) ? 0.5 : 0);
    }

    var emph = arrowFocus || (engaged && stageIdx === 1 ? 'dGx' : null);
    aGx.line.stroke({ width: emph === 'dGx' ? 3.6 : 1.7 });
    aG0.line.stroke({ width: emph === 'dG0' ? 3.6 : 1.7 });
    lblGx.font({ weight: emph === 'dGx' ? 'bold' : 'normal' });
    lblG0.font({ weight: emph === 'dG0' ? 'bold' : 'normal' });
    extTS1.opacity(emph === 'dGx' ? 1 : 0);
    extReact.opacity(emph ? 1 : 0);
    extProd.opacity(emph === 'dG0' ? 1 : 0);
  }

  window.update_pathwayStage = function (v) { stageIdx = v; engaged = true; render(); };
  window.toggle_branchChoice = function (on) {
    branch = on ? 'Addition' : 'Substitution'; engaged = true; render();
  };
  window.trigger_energyArrow = function () {
    clickArrow(arrowFocus === null ? 'dGx' : (arrowFocus === 'dGx' ? 'dG0' : null));
  };
  window.resetFig = function () {
    engaged = false; arrowFocus = null; stageIdx = 0; branch = 'Substitution'; stepIdx = 0;
    document.getElementById('pathwayStageInput').value = 0;
    document.getElementById('pathwayStageVal').value = STAGE_NAMES[0];
    document.getElementById('branchChoiceInput').checked = false;
    syncStepText(); hidePopup(); render();
  };

  /* ---------------- demo steps ---------------- */
  var steps = [
    { t: 'Reactants on the baseline', n: 'Benzene and Br₂ sit on the left dashed level; everything else in the diagram is measured vertically against this line.', s: 0, b: false },
    { t: 'The big first barrier', n: 'The black curve climbs steeply to the first transition state. Breaking benzene\'s aromaticity to attack Br⁺ costs a large ΔG‡, which is why bromination needs an FeBr₃ catalyst.', s: 1, b: false },
    { t: 'The carbocation intermediate', n: 'The curve drops into a real minimum: the cyclohexadienyl cation, with H and Br on the same sp³ carbon and a delocalized positive charge. It is a genuine, if fleeting, species — not a transition state.', s: 2, b: false },
    { t: 'Second, smaller barrier', n: 'Loss of H⁺ from the sp³ carbon crosses a much lower maximum — this step is fast compared with the first.', s: 3, b: false },
    { t: 'Substitution ends downhill', n: 'Bromobenzene plus HBr land below the reactant level: the aromatic ring is restored, so ΔG° is negative and the reaction is favorable.', s: 4, b: false },
    { t: 'The road not taken: addition', n: 'Switch the branch and the magenta curve leaves the same intermediate but finishes ABOVE the reactants — the dibromide has no aromatic stabilization, so addition is uphill and does not occur.', s: 4, b: true }
  ];
  var stepIdx = 0;

  function syncStepText() {
    var s = steps[stepIdx];
    document.getElementById('stepTitle').textContent = s.t;
    document.getElementById('demoNarration').textContent = s.n;
    document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + ' / ' + steps.length;
  }
  function applyStep() {
    var s = steps[stepIdx];
    stageIdx = s.s; branch = s.b ? 'Addition' : 'Substitution';
    document.getElementById('pathwayStageInput').value = s.s;
    document.getElementById('pathwayStageVal').value = STAGE_NAMES[s.s];
    document.getElementById('branchChoiceInput').checked = s.b;
    syncStepText();
    render();
  }
  window.nextStep = function () { if (stepIdx < steps.length - 1) { stepIdx++; engaged = true; applyStep(); } };
  window.prevStep = function () { if (stepIdx > 0) { stepIdx--; engaged = true; applyStep(); } };

  syncStepText();
  render();
  window.__markRendered();
})();
// @FIGURE_CODE_END

