// @FIGURE_CODE_BEGIN
(function () {
  var MAG = '#e6007e', BLK = '#000', GRAY = '#c4c4c4';
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, 880, 580);

  /* ---------------- text helpers ---------------- */
  function txt(parent, s, x, y, o) {
    o = o || {};
    var t = parent.text(s);
    t.font({
      family: 'Helvetica, Arial, sans-serif',
      size: o.size || 20,
      weight: o.weight || 'normal',
      style: o.style || 'normal',
      anchor: o.anchor || 'middle'
    });
    t.fill(o.fill || '#000');
    t.attr({ x: x, y: y, 'dominant-baseline': 'central' });
    t.node.setAttribute('xml:space', 'preserve');
    var first = t.node.firstChild;
    if (first && first.setAttribute) {
      first.setAttribute('x', x);
      first.setAttribute('dy', 0);
      first.setAttribute('dominant-baseline', 'central');
      first.setAttribute('xml:space', 'preserve');
    }
    if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': o.haloW || 4.5, 'stroke-linejoin': 'round' });
    return t;
  }
  function textWidth(t, s, size) {
    var w = 0;
    try { w = t.node.getComputedTextLength(); } catch (e) { w = 0; }
    if (!w || !isFinite(w)) { try { w = t.bbox().width; } catch (e2) { w = 0; } }
    if (!w || !isFinite(w)) w = s.length * size * 0.6;
    return w;
  }
  /* One typographic run: several parts kept on a single baseline with real
     kerning. Word separation is ALWAYS an explicit numeric gap (never a leading
     or trailing space, which SVG would collapse), so "(does not occur)" keeps
     its spaces. */
  function chem(parent, x, y, parts, anchor, halo) {
    var g = parent.group();
    var cx = 0, els = [];
    for (var i = 0; i < parts.length; i++) {
      var p = parts[i], sz = p.size || 20;
      var t = txt(g, p.s, cx, (p.dy || 0), {
        size: sz, fill: p.fill, weight: p.weight, style: p.style,
        anchor: 'start', halo: halo, haloW: 4.5
      });
      els.push(t);
      cx += textWidth(t, p.s, sz) + (p.gap || 0);
    }
    var tx = x;
    if (anchor === 'middle') tx = x - cx / 2;
    else if (anchor === 'end') tx = x - cx;
    g.attr('transform', 'translate(' + tx + ',' + y + ')');
    return { g: g, w: cx, els: els };
  }
  function setRunWeight(run, w) {
    for (var i = 0; i < run.els.length; i++) run.els[i].font({ weight: w });
  }
  function ptsStr(a) { return a.map(function (p) { return p[0] + ',' + p[1]; }).join(' '); }
  function catmull(P, per) {
    var out = [];
    for (var i = 0; i < P.length - 1; i++) {
      var p0 = P[Math.max(0, i - 1)], p1 = P[i], p2 = P[i + 1], p3 = P[Math.min(P.length - 1, i + 2)];
      for (var j = 0; j < per; j++) {
        var t = j / per, t2 = t * t, t3 = t2 * t;
        out.push([
          0.5 * ((2 * p1[0]) + (-p0[0] + p2[0]) * t + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3),
          0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * t + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3)
        ]);
      }
    }
    out.push(P[P.length - 1].slice());
    return out;
  }
  function dash(parent, x1, y1, x2, y2, o) {
    o = o || {};
    return parent.line(x1, y1, x2, y2).stroke({
      color: o.color || '#000', width: o.width || 2.4,
      dasharray: o.dasharray || '11,8', linecap: 'butt'
    });
  }
  function hit(g, x, y, w, h) { return g.rect(w, h).move(x, y).fill({ color: '#fff', opacity: 0 }); }
  function bind(el, tip, title, body) {
    el.css('cursor', 'pointer');
    el.on('mousemove', function (e) { showTooltip(tip, e); });
    el.on('mouseleave', function () { hideTooltip(); });
    if (title) el.on('click', function () { showPopup(title, body); });
  }

  /* ---------------- energy arrow (outside panel, left) ---------------- */
  var grad = draw.gradient('linear', function (add) {
    add.stop(0, '#ef5a24'); add.stop(0.42, '#f79a4e'); add.stop(0.76, '#fbd98a'); add.stop(1, '#fdf9cf');
  });
  grad.attr({ x1: 0, y1: 0, x2: 0, y2: 1 });
  draw.path('M18,534 L18,74 L2,74 L36,8 L70,74 L54,74 L54,534 Z')
    .fill(grad).stroke({ color: '#000', width: 1 });
  var enTxt = txt(draw, 'Energy', 36, 305, { size: 23, weight: 'bold' });
  enTxt.rotate(-90, 36, 305);

  /* ---------------- panel ---------------- */
  var panel = draw.rect(784, 530).move(88, 6).fill('#dfeefb').stroke({ color: '#000', width: 1.2 });
  bind(panel, 'Reaction–energy diagram: vertical = free energy, horizontal = reaction progress');

  var glowLayer = draw.group();
  var curveLayer = draw.group();
  var annLayer = draw.group();
  var structLayer = draw.group();

  /* ---------------- energy levels ---------------- */
  var REACT_Y = 312, PROD_Y = 372, TS1_Y = 31;
  var extTS1 = dash(annLayer, 92, TS1_Y, 868, TS1_Y, { color: '#6b6b6b', width: 1.4, dasharray: '7,6' }).opacity(0);
  var extReact = dash(annLayer, 92, REACT_Y, 868, REACT_Y, { color: '#6b6b6b', width: 1.4, dasharray: '7,6' }).opacity(0);
  var extProd = dash(annLayer, 92, PROD_Y, 868, PROD_Y, { color: '#6b6b6b', width: 1.4, dasharray: '7,6' }).opacity(0);

  dash(annLayer, 212, REACT_Y, 356, REACT_Y, { width: 2.4 });
  dash(annLayer, 370, PROD_Y, 616, PROD_Y, { width: 2.4 });
  dash(annLayer, 292, TS1_Y, 366, TS1_Y, { width: 2.4, dasharray: '10,7' });

  /* ---------------- curves ---------------- */
  var SUB_PTS = [[208, 312], [248, 306], [272, 252], [296, 148], [313, 72], [330, 40], [350, 56], [372, 96],
  [396, 124], [415, 132], [438, 120], [462, 97], [479, 86], [496, 84], [513, 97], [531, 132],
  [551, 216], [571, 300], [591, 351], [609, 368], [622, 372]];
  var ADD_PTS = [[415, 132], [440, 118], [465, 100], [490, 90], [512, 86], [530, 88], [549, 108], [568, 148],
  [588, 191], [606, 213], [620, 220], [630, 222]];
  var PER = 12;
  var SUB = catmull(SUB_PTS, PER), ADD = catmull(ADD_PTS, PER);
  var TROUGH_I = 9 * PER;
  var shared = SUB.slice(0, TROUGH_I + 1), subB = SUB.slice(TROUGH_I);

  function argmin(arr, a, b) { var k = a; for (var i = a; i <= b; i++) if (arr[i][1] < arr[k][1]) k = i; return k; }
  var TS1_I = argmin(SUB, 0, TROUGH_I);
  var TS2_I = argmin(SUB, TROUGH_I, SUB.length - 1);
  var ADDMAX_I = argmin(ADD, 0, ADD.length - 1);

  var subHalo = curveLayer.polyline(ptsStr(subB)).fill('none')
    .stroke({ color: '#ffd24d', width: 12, linecap: 'round', linejoin: 'round' }).opacity(0);
  var addHalo = curveLayer.polyline(ptsStr(ADD)).fill('none')
    .stroke({ color: '#ffb3d9', width: 12, linecap: 'round', linejoin: 'round' }).opacity(0);
  var addLine = curveLayer.polyline(ptsStr(ADD)).fill('none')
    .stroke({ color: MAG, width: 3.8, linecap: 'round', linejoin: 'round' });
  var subLine = curveLayer.polyline(ptsStr(subB)).fill('none')
    .stroke({ color: BLK, width: 3.8, linecap: 'round', linejoin: 'round' });
  var sharedLine = curveLayer.polyline(ptsStr(shared)).fill('none')
    .stroke({ color: BLK, width: 3.8, linecap: 'round', linejoin: 'round' });

  bind(sharedLine, 'Step 1 (slow): benzene attacks Br⁺ — the big barrier ΔG‡',
    'Step 1: the rate-limiting climb',
    'Attacking the electrophile destroys benzene\'s aromatic ring, so this first transition state lies very high above the reactants. Its ΔG‡ controls how fast bromination goes, which is why a Lewis-acid catalyst (FeBr₃) is required to make Br₂ electrophilic enough.');
  bind(subLine, 'Substitution branch: loss of H⁺ restores aromaticity — ends BELOW the reactants',
    'Substitution branch',
    'From the carbocation intermediate, loss of H⁺ from the sp³ carbon crosses a much smaller second barrier and regenerates the aromatic ring. Because roughly 150 kJ/mol of aromatic stabilization is recovered, bromobenzene + HBr sit below the reactant level: ΔG° is negative and the reaction is favorable.');
  bind(addLine, 'Addition branch: aromaticity lost for good — ends ABOVE the reactants',
    'Addition branch (does not occur)',
    'If bromide added to the cation instead, the product would be a non-aromatic dibromocyclohexadiene. That product has permanently sacrificed the aromatic stabilization energy, so it lies above benzene + Br₂: the step is endergonic and is not observed.');

  /* ---------------- ΔG arrows ---------------- */
  function vArrow(parent, x, y1, y2, color, width) {
    var g = parent.group();
    var ln = g.line(x, y1 + 8, x, y2 - 8).stroke({ color: color, width: width, linecap: 'butt' });
    var hs = 10;
    g.polygon(ptsStr([[x, y1], [x - hs * 0.5, y1 + hs], [x + hs * 0.5, y1 + hs]])).fill(color);
    g.polygon(ptsStr([[x, y2], [x - hs * 0.5, y2 - hs], [x + hs * 0.5, y2 - hs]])).fill(color);
    return { g: g, line: ln };
  }
  var aGx = vArrow(annLayer, 330, TS1_Y + 4, REACT_Y, BLK, 2.0);
  var aG0 = vArrow(annLayer, 430, REACT_Y, PROD_Y, BLK, 2.0);
  /* ΔG‡ sits in the open wedge left of the arrow and BELOW the ascending curve,
     which at this height has already moved out to x ≈ 268. */
  var lblGx = chem(annLayer, 322, 262, [
    { s: 'ΔG', size: 23, style: 'italic' }, { s: '‡', size: 15, dy: -9 }
  ], 'end', true);
  var lblG0 = chem(annLayer, 442, 340, [
    { s: 'ΔG', size: 23, style: 'italic' }, { s: '°', size: 18, dy: 1.5 }
  ], 'start', true);
  var hitGx = hit(annLayer, 276, TS1_Y, 84, REACT_Y - TS1_Y);
  var hitG0 = hit(annLayer, 404, REACT_Y - 6, 90, PROD_Y - REACT_Y + 12);

  var arrowFocus = null;
  function clickArrow(which) {
    arrowFocus = (arrowFocus === which) ? null : which;
    engaged = true; render();
    if (arrowFocus === 'dGx') {
      showPopup('ΔG‡ — how FAST', 'ΔG‡ is the vertical climb from the reactant level up to the highest transition state. It says nothing about whether the reaction is favorable; it only sets the rate. Here it is large, so bromination of benzene needs a catalyst.');
    } else if (arrowFocus === 'dG0') {
      showPopup('ΔG° — how FAVORABLE', 'ΔG° is the net vertical drop from reactants to products. For substitution it is negative (products below reactants, aromaticity regained); for the addition branch the same measurement would be positive, which is why that product never forms.');
    } else { hidePopup(); }
  }
  bind(hitGx, 'ΔG‡ — activation barrier (rate). Click to extend its reference levels.');
  hitGx.on('click', function () { clickArrow('dGx'); });
  bind(hitG0, 'ΔG° — net free-energy change (favorability). Click to extend its reference levels.');
  hitG0.on('click', function () { clickArrow('dG0'); });

  /* ---------------- structures ---------------- */
  function hexPts(cx, cy, r) {
    var p = [];
    for (var k = 0; k < 6; k++) { var a = (90 + 60 * k) * Math.PI / 180; p.push([cx + r * Math.cos(a), cy - r * Math.sin(a)]); }
    return p;
  }
  function ring(g, cx, cy, r, dbl) {
    var p = hexPts(cx, cy, r);
    g.polygon(ptsStr(p)).fill('none').stroke({ color: BLK, width: 2.4, linejoin: 'round' });
    dbl.forEach(function (i) {
      var a = p[i], b = p[(i + 1) % 6];
